package dev.aivillages.e2e.paralleld;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.Container;
import net.minecraft.world.entity.npc.villager.Villager;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.storage.TagValueOutput;
import net.minecraft.util.ProblemReporter;
final class DObservedParticipants {
 static Map<String,Object> block(BlockPos p){return Map.of("pos",List.of(p.getX(),p.getY(),p.getZ()));}
 static Map<String,Object> entity(Villager v){return Map.of("entity",v.getUUID(),"pos",List.of((int)Math.floor(v.getX()),(int)Math.floor(v.getY()),(int)Math.floor(v.getZ())));}
 static JsonObject descriptor(DChestCourierScene c,DVillagerHandoffScene h){return DComeScene.JSON.toJsonTree(Map.of("participants",Map.of("courier",Map.of("source",block(c.sourcePos),"carrier",entity(c.arena.actor),"destination",block(c.destPos),"item","minecraft:oak_planks"),"handoff",Map.of("sender",entity(h.base.arena.actor),"recipient",entity(h.receiver),"item","minecraft:oak_planks")))).getAsJsonObject();}
 static JsonObject load(Path f){try{return JsonParser.parseString(Files.readString(f)).getAsJsonObject();}catch(Exception e){throw new RuntimeException(e);}}
 static boolean loaded(ServerLevel level,JsonObject descriptor){for(var c:descriptor.getAsJsonObject("participants").entrySet())for(var entry:c.getValue().getAsJsonObject().entrySet()){if(!entry.getValue().isJsonObject())continue;var p=entry.getValue().getAsJsonObject();if(p.has("entity")){if(!(level.getEntity(UUID.fromString(p.get("entity").getAsString())) instanceof Villager))return false;}else{var x=p.getAsJsonArray("pos");var at=new BlockPos(x.get(0).getAsInt(),x.get(1).getAsInt(),x.get(2).getAsInt());if(!level.hasChunkAt(at) || !(level.getBlockEntity(at) instanceof Container))return false;}}return true;}
 static Map<String,List<Integer>> capture(ServerLevel level,JsonObject d,String event,Path output){return capture(level,d,event,output,"D10-GT01");}
 static Map<String,List<Integer>> capture(ServerLevel level,JsonObject d,String event,Path output,String caseId){var cases=new TreeMap<String,Object>();var vectors=new TreeMap<String,List<Integer>>();for(var ce:d.getAsJsonObject("participants").entrySet()){var spec=ce.getValue().getAsJsonObject();var rows=new TreeMap<String,Object>();var vector=new ArrayList<Integer>();for(String role:ce.getKey().equals("courier")?List.of("source","carrier","destination"):List.of("sender","recipient")){var p=spec.getAsJsonObject(role);var pos=p.getAsJsonArray("pos");var at=new BlockPos(pos.get(0).getAsInt(),pos.get(1).getAsInt(),pos.get(2).getAsInt());Container c;String nbt;var row=new TreeMap<String,Object>();if(p.has("entity")){var e=level.getEntity(UUID.fromString(p.get("entity").getAsString()));if(!(e instanceof Villager v))throw new IllegalStateException("actual restored native villager "+p);c=v.getInventory();var saved=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,level.registryAccess());if(!v.save(saved))throw new IllegalStateException("native serialization");nbt=saved.buildResult().toString();row.put("entity",v.getUUID());row.put("navigation_active",!v.getNavigation().isDone());}else{if(!level.hasChunkAt(at))throw new IllegalStateException("saved block unloaded");var be=level.getBlockEntity(at);c=(Container)be;nbt=be.saveWithFullMetadata(level.registryAccess()).toString();row.put("marker",be instanceof dev.aivillages.fabric.storage.StorageMarkerAccess a?a.cognitivecraft$marker():null);}int n=0;var slots=new ArrayList<Map<String,Object>>();for(int i=0;i<c.getContainerSize();i++){var x=c.getItem(i);String id=x.isEmpty()?null:net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(x.getItem()).toString();if(Objects.equals(id,spec.get("item").getAsString()))n+=x.getCount();var sr=new TreeMap<String,Object>();sr.put("slot",i);sr.put("id",id);sr.put("count",x.getCount());slots.add(sr);}vector.add(n);row.put("count",n);row.put("slots",slots);row.put("native_nbt",nbt);rows.put(role,row);}vectors.put(ce.getKey(),vector);cases.put(ce.getKey(),Map.of("vector",vector,"roles",rows));}var r=new TreeMap<String,Object>();r.put("case",caseId);r.put("event",event);r.put("tick",level.getGameTime());r.put("world",DTestAuthority.acquireTaggedWorld().world());r.put("native_seed",level.getSeed());r.put("participants",cases);r.put("integration_root",null);r.put("effect_id",null);r.put("save_proof",null);r.put("classification","UNKNOWN_NATIVE_PARTICIPANT_PERSISTENCE");r.put("pid",ProcessHandle.current().pid());r.put("jvm_start_ms",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());DComeScene.writeLine(output.resolve("restart.jsonl"),r);System.out.println("CC_D10_RESTART "+DComeScene.JSON.toJson(r));return vectors;}
}
